 public sealed partial class MainWindow {
  readonly Dictionary<string,TextBlock> statusValues=new Dictionary<string,TextBlock>();ListBox projectList,profileList,wallpaperList;readonly Dictionary<string,Button> projectButtons=new Dictionary<string,Button>();TextBox projectSearch;TextBlock profileDetails,sensorDetails,projectEmpty;ComboBox targetDisplay;TextBlock assignmentText;System.IO.FileSystemWatcher wallpaperWatcher;readonly System.Windows.Threading.DispatcherTimer wallpaperDebounce=new System.Windows.Threading.DispatcherTimer();Dictionary<string,object> liveSensors;
  bool RenderUxPage(string name){statusValues.Clear();if(name=="overview"){BuildOverview();return true;}if(name=="projects"){BuildProjects();return true;}if(name=="profiles"){BuildProfiles();return true;}if(name=="wallpaper"){BuildGallery();return true;}if(name=="diagnostics"){BuildDiagnostics();return true;}if(name=="sensors"){BuildSensors();return true;}if(name=="dock"&&File.Exists(Path.Combine(root,"state","dock-live-apply-hold.json"))){Text("Dock 자동 적용 보류",false);Text("적용 시험 뒤 Explorer 프로세스 교체가 관찰됐습니다. 원인 확인 전에는 기존 Dock 값을 유지하며 자동 적용하지 않습니다. Windhawk에서 직접 확인할 수 있습니다.",true);foreach(var f in vm.Fields)Text(f.Label+": "+Convert.ToString(f.Value));vm.Fields.Clear();var held=Actions();Action(held,"Windhawk 설정",()=>vm.Service.Recover("windhawk-open"));return true;}if(name=="dock"){Text("Windows 기본 작업 표시줄의 앱 전환·고정 앱을 유지합니다. 값은 Windhawk 설정으로 내보냅니다.",true);foreach(var f in vm.Fields)AddField(f);Text("위치: 하단 · 정렬: 중앙 기준, 오른쪽 트레이 앞까지 필요한 만큼 이동\n최대 폭 비율은 현재 계산 참고값이며 강제 폭 제한은 제공하지 않습니다. Hover 확대는 현재 조합에서 지원하지 않아 꺼져 있습니다.",true);var a=Actions();Action(a,"Windhawk 설정",()=>vm.Service.Recover("windhawk-open"));return true;}if(name=="monitor"){Text("측정 엔진은 유지하며 표시와 갱신 정책만 변경합니다.",true);foreach(var f in vm.Fields)AddField(f);var m=vm.Service.Read("monitor");Text("현재 저장된 레이아웃: "+(DesktopService.B(m,"compact")?"간단히":"자세히")+" · CPU 그래프 "+DesktopService.B(m,"showCpuGraph")+" · 네트워크 그래프 "+DesktopService.B(m,"showNetworkGraph"),true);return true;}if(name=="automation"){foreach(var f in vm.Fields)AddField(f);Text("프로필 자동 전환은 아직 지원하지 않습니다. 프로필 페이지에서 직접 미리보고 적용하세요. 전체 화면·배터리 중지 정책은 기존 Lively 설정을 따릅니다.",true);var a=Actions();Action(a,"시작 복원 수동 실행",Desktop("startup-recover"));Action(a,"Lively 절전 설정",Desktop("wallpaper-settings"));return true;}return false;}
  void RefreshUx(){if(page=="overview"){try{foreach(var row in vm.Service.Health()){TextBlock value;if(statusValues.TryGetValue(row.Id,out value)){string text=row.Status+" · "+row.Detail;if(value.Text!=text)value.Text=text;}}}catch(Exception e){vm.Status="상태 갱신 확인 필요: "+e.Message;}}else if(page=="sensors")RefreshSensorDetails();}
  void BuildOverview(){var a=Actions();Action(a,"모니터 표시 / 숨김",Desktop("monitor-toggle"));Action(a,"배경 재생 / 정지",Desktop("wallpaper-toggle"));PageButton(a,"프로필 선택","profiles");PageButton(a,"프로젝트","projects");foreach(var row in vm.Service.Health().Where(x=>!x.Id.StartsWith("config-")))StatusRow(row,true);a=Actions();PageButton(a,"진단 및 복구","diagnostics");var command=new Button{Content="명령 찾기 · "+DesktopService.S(vm.Service.Optional("ux"),"commandPaletteShortcut","Ctrl+K")};command.Click+=delegate{OpenCommandPalette();};a.Children.Add(command);}
  void PageButton(Panel panel,string label,string destination){var button=new Button{Content=label};button.Click+=delegate{SelectPage(destination);};panel.Children.Add(button);}
  void StatusRow(HealthEntry row,bool watch){var grid=new Grid{Margin=new Thickness(0,0,0,4)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(140)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var name=new TextBlock{Text=row.Name,VerticalAlignment=VerticalAlignment.Center};grid.Children.Add(name);var value=new TextBlock{Text=row.Status+" · "+row.Detail+(watch?"":" · "+row.Checked.ToString("HH:mm:ss")),Foreground=Muted,TextWrapping=TextWrapping.Wrap,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(8,4,12,8)};Grid.SetColumn(value,1);grid.Children.Add(value);if(watch)statusValues[row.Id]=value;if(!String.IsNullOrEmpty(row.Action)){var b=new Button{Content=row.ActionLabel};b.Click+=delegate{if(row.Action.StartsWith("page:"))SelectPage(row.Action.Substring(5));else Run(()=>vm.Service.Recover(row.Action));};Grid.SetColumn(b,2);grid.Children.Add(b);}content.Children.Add(new Border{Child=grid,BorderBrush=Line,BorderThickness=new Thickness(0,0,0,1),Margin=new Thickness(0,0,0,7)});}
  void BuildProjects(){projectButtons.Clear();Text("폴더·IDE·터미널을 한 곳에서 엽니다. 명령은 직접 실행할 때만 동작합니다.",true);Text("프로젝트 검색",true);projectSearch=new TextBox{Margin=new Thickness(0,0,0,10)};AutomationProperties.SetName(projectSearch,"프로젝트 검색");content.Children.Add(projectSearch);var a=Actions();Action(a,"프로젝트 추가",()=>{Dispatcher.Invoke((Action)(()=>EditProject(null)));return "프로젝트 편집을 마쳤습니다.";});Action(a,"최근 사용 순",()=>{Dispatcher.Invoke((Action)(()=>RefreshProjects(true)));return "실제 최근 실행 기록 순으로 표시했습니다.";});projectEmpty=new TextBlock{Text="등록된 프로젝트가 없습니다. 실제 폴더를 선택해 추가하세요.",Foreground=Muted,Margin=new Thickness(0,6,0,10)};content.Children.Add(projectEmpty);projectList=new ListBox{Height=260,Background=Secondary,Foreground=TextColor,BorderBrush=Line};AutomationProperties.SetName(projectList,"프로젝트 목록");content.Children.Add(projectList);projectList.SelectionChanged+=delegate{ProjectAvailability();};projectSearch.TextChanged+=delegate{RefreshProjects(false);};a=Actions();foreach(var pair in new[]{new[]{"폴더 열기","folder"},new[]{"VS Code","ide"},new[]{"터미널","terminal"},new[]{"GitHub","repository"}}){string action=pair[1];projectButtons[action]=Action(a,pair[0],()=>vm.Service.LaunchProject(SelectedProject().Id,action));}Action(a,"편집 / 경로 복구",()=>{var p=SelectedProject();Dispatcher.Invoke((Action)(()=>EditProject(p)));return "프로젝트 편집을 마쳤습니다.";});Action(a,"고정 전환",()=>{var p=SelectedProject();p.Pinned=!p.Pinned;vm.Service.SaveProject(p);Dispatcher.Invoke((Action)(()=>RefreshProjects(false)));return "고정 상태를 저장했습니다.";});a=Actions();foreach(int delta in new[]{-1,1}){int d=delta;Action(a,d<0?"위로":"아래로",()=>{var p=SelectedProject();vm.Service.MoveProject(p.Id,d);Dispatcher.Invoke((Action)(()=>RefreshProjects(false)));return "같은 고정 그룹 안에서 순서를 저장했습니다.";});}Action(a,"설정한 명령 실행",()=>{var p=SelectedProject();if(p.Commands==null||p.Commands.Count==0)throw new ArgumentException("설정된 명령이 없습니다.");bool ok=Dispatcher.Invoke(new Func<bool>(()=>Decide("프로젝트 명령 실행",p.Name+"\n작업 폴더: "+p.Directory+"\n\n"+p.Commands[0],"이 명령 실행","취소")==0));if(!ok)return "명령 실행을 취소했습니다.";return vm.Service.LaunchProject(p.Id,"command");});Action(a,"목록에서 삭제",()=>{var p=SelectedProject();bool ok=Dispatcher.Invoke(new Func<bool>(()=>Decide("프로젝트 삭제",p.Name+"을 목록에서만 삭제할까요? 실제 폴더와 파일은 유지합니다.","목록에서 삭제","취소")==0));if(ok){vm.Service.DeleteProject(p.Id);Dispatcher.Invoke((Action)(()=>RefreshProjects(false)));}return ok?"프로젝트 목록에서 삭제했습니다.":"삭제를 취소했습니다.";});RefreshProjects(false);}
  void ProjectAvailability(){var selected=projectList.SelectedItem as ProjectEntry;bool exists=selected!=null&&Directory.Exists(selected.Directory);var apps=vm.Service.Optional("apps");foreach(var pair in projectButtons){bool supported=exists;if(pair.Key=="ide")supported&=File.Exists(DesktopService.S(apps,"code"));if(pair.Key=="terminal")supported&=File.Exists(DesktopService.S(apps,"terminal"));if(pair.Key=="repository")supported&=selected!=null&&!String.IsNullOrEmpty(selected.RepositoryUrl);pair.Value.IsEnabled=supported;pair.Value.ToolTip=supported?null:"프로젝트 폴더 또는 연결된 프로그램·URL 설정이 필요합니다.";ToolTipService.SetShowOnDisabled(pair.Value,true);}}
  ProjectEntry SelectedProject(){return Dispatcher.Invoke(new Func<ProjectEntry>(()=>{var p=projectList.SelectedItem as ProjectEntry;if(p==null)throw new ArgumentException("프로젝트를 먼저 선택하세요.");return p;}));}
  void RefreshProjects(bool recent){var entries=vm.Service.Projects().Where(x=>String.IsNullOrEmpty(projectSearch.Text)||(x.Name+" "+x.Directory).IndexOf(projectSearch.Text,StringComparison.OrdinalIgnoreCase)>=0);if(recent){var history=vm.Service.State("project-recent");entries=entries.OrderByDescending(x=>DesktopService.S(history,x.Id));}projectList.ItemsSource=entries.ToArray();if(projectList.Items.Count>0)projectList.SelectedIndex=0;else vm.Status="표시할 프로젝트가 없습니다. 검색어를 지우거나 프로젝트를 추가하세요.";ProjectAvailability();projectEmpty.Visibility=projectList.Items.Count==0?Visibility.Visible:Visibility.Collapsed;projectList.Height=projectList.Items.Count==0?90:260;}
  void EditProject(ProjectEntry existing){var w=new Window{Title=existing==null?"프로젝트 추가":"프로젝트 편집",Owner=this,Width=600,Height=590,Background=Surface,Foreground=TextColor,FontFamily=FontFamily,WindowStartupLocation=WindowStartupLocation.CenterOwner};var stack=new StackPanel{Margin=new Thickness(20)};w.Content=new ScrollViewer{Content=stack,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};var fields=new Dictionary<string,TextBox>();foreach(var label in new[]{"이름","폴더 경로","GitHub HTTPS 주소","직접 실행할 PowerShell 명령 (선택)"}){stack.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,0,0,5)});var box=new TextBox{Margin=new Thickness(0,0,0,12),Padding=new Thickness(6)};AutomationProperties.SetName(box,label);fields[label]=box;stack.Children.Add(box);}if(existing!=null){fields["이름"].Text=existing.Name;fields["폴더 경로"].Text=existing.Directory;fields["GitHub HTTPS 주소"].Text=existing.RepositoryUrl;fields["직접 실행할 PowerShell 명령 (선택)"].Text=existing.Commands==null?"":existing.Commands.FirstOrDefault()??"";}var pin=new CheckBox{Content="자주 쓰는 프로젝트로 고정",Foreground=TextColor,IsChecked=existing!=null&&existing.Pinned,Margin=new Thickness(0,0,0,12)};stack.Children.Add(pin);var error=new TextBlock{TextWrapping=TextWrapping.Wrap,Foreground=Accent};stack.Children.Add(error);var actions=new WrapPanel();stack.Children.Add(actions);var browse=new Button{Content="폴더 선택",Padding=new Thickness(10),Margin=new Thickness(0,0,8,0)};browse.Click+=delegate{using(var dialog=new System.Windows.Forms.FolderBrowserDialog()){dialog.ShowNewFolderButton=false;if(dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK)fields["폴더 경로"].Text=dialog.SelectedPath;}};actions.Children.Add(browse);bool saved=false;string initial=String.Join("\n",fields.Values.Select(x=>x.Text))+"|"+pin.IsChecked;var save=new Button{Content="프로젝트 저장",Padding=new Thickness(10),IsDefault=true};save.Click+=delegate{try{var p=new ProjectEntry{Id=existing==null?Guid.NewGuid().ToString("N"):existing.Id,Name=fields["이름"].Text.Trim(),Directory=fields["폴더 경로"].Text.Trim(),RepositoryUrl=fields["GitHub HTTPS 주소"].Text.Trim(),Ide="vscode",Terminal="powershell",Pinned=pin.IsChecked==true,Order=existing==null?vm.Service.Projects().Length:existing.Order,Commands=String.IsNullOrWhiteSpace(fields["직접 실행할 PowerShell 명령 (선택)"].Text)?new List<string>():new List<string>{fields["직접 실행할 PowerShell 명령 (선택)"].Text}};vm.Service.SaveProject(p);saved=true;w.DialogResult=true;}catch(Exception e){error.Text=e.Message;}};actions.Children.Add(save);actions.Children.Add(new Button{Content="취소",IsCancel=true,Padding=new Thickness(10),Margin=new Thickness(8,0,0,0)});w.Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(saved||initial==String.Join("\n",fields.Values.Select(x=>x.Text))+"|"+pin.IsChecked)return;var choice=MessageBox.Show(w,"저장하지 않은 프로젝트 변경이 있습니다.\n예: 저장 후 닫기 · 아니요: 버리고 닫기 · 취소: 계속 편집","미저장 프로젝트",MessageBoxButton.YesNoCancel,MessageBoxImage.Question,MessageBoxResult.Cancel);if(choice==MessageBoxResult.Cancel)e.Cancel=true;else if(choice==MessageBoxResult.Yes){e.Cancel=true;w.Dispatcher.BeginInvoke((Action)(()=>save.RaiseEvent(new RoutedEventArgs(Button.ClickEvent))));}};w.ShowDialog();RefreshProjects(false);}
  string Prompt(string title,string initial=""){string result=null;var w=new Window{Title=title,Owner=this,Width=460,Height=190,Background=Surface,Foreground=TextColor,FontFamily=FontFamily,WindowStartupLocation=WindowStartupLocation.CenterOwner};var stack=new StackPanel{Margin=new Thickness(18)};w.Content=stack;var text=new TextBox{Text=initial,Margin=new Thickness(0,0,0,14)};AutomationProperties.SetName(text,"프로필 이름");stack.Children.Add(text);var button=new Button{Content="이 이름으로 저장",Padding=new Thickness(10)};button.Click+=delegate{if(!String.IsNullOrWhiteSpace(text.Text)){result=text.Text.Trim();w.DialogResult=true;}};stack.Children.Add(button);w.ShowDialog();return result;}
  void BuildProfiles(){Text("현재: "+vm.Service.ProfileState(),true);var previous=vm.Service.State("profile-previous");Text("이전 상태: "+DesktopService.S(previous,"name","복원 기록 없음")+" · "+DesktopService.S(previous,"created"),true);profileList=new ListBox{Height=160,Background=Secondary,Foreground=TextColor,BorderBrush=Line};AutomationProperties.SetName(profileList,"작업공간 프로필 목록");profileList.ItemsSource=vm.Service.Profiles();content.Children.Add(profileList);profileDetails=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,8),Foreground=Muted};content.Children.Add(profileDetails);profileList.SelectionChanged+=delegate{var p=profileList.SelectedItem as ProfileEntry;if(p!=null)profileDetails.Text=vm.Service.ProfilePreview(p);};if(profileList.Items.Count>0)profileList.SelectedIndex=0;var request=vm.Service.State("profile-request");if(request.ContainsKey("id"))profileList.SelectedItem=profileList.Items.Cast<ProfileEntry>().FirstOrDefault(x=>x.Id==DesktopService.S(request,"id"))??profileList.SelectedItem;var a=Actions();Action(a,"변경 미리보기 후 적용",()=>{var p=Dispatcher.Invoke(new Func<ProfileEntry>(()=>profileList.SelectedItem as ProfileEntry));if(p==null)throw new ArgumentException("프로필을 선택하세요.");string preview=vm.Service.ProfilePreview(p);if(!Dispatcher.Invoke(new Func<bool>(()=>Decide("프로필 적용 · "+p.Name,preview,"프로필 적용","취소")==0)))return "프로필 적용을 취소했습니다.";vm.Service.Action("profile-apply",p.Id);Dispatcher.Invoke((Action)(()=>Show("profiles")));return "프로필 적용: "+p.Name+". 실제 표시·재생 요청 결과를 확인했습니다.";});Action(a,"이전 상태로 한 번 복원",()=>{var prior=vm.Service.State("profile-previous");if(prior.Count==0)throw new ArgumentException("돌아갈 이전 상태가 없습니다.");if(!Dispatcher.Invoke(new Func<bool>(()=>Decide("이전 작업공간 복원","모니터 표시·간단한 모드·수동 재생 정책만 돌아갑니다. 저장된 배경 선택과 위치는 유지합니다.","이전 상태 복원","취소")==0)))return "복원을 취소했습니다.";vm.Service.Action("profile-restore");Dispatcher.Invoke((Action)(()=>Show("profiles")));return "이전 작업공간을 복원하고 복원 기록을 소비했습니다.";});a=Actions();Action(a,"현재 상태를 새 프로필로",()=>{string name=Dispatcher.Invoke(new Func<string>(()=>Prompt("현재 작업공간 저장")));if(name==null)return "저장을 취소했습니다.";vm.Service.SaveWorkspaceProfile(name);Dispatcher.Invoke((Action)(()=>Show("profiles")));return "현재 세 가지 작업공간 상태를 저장했습니다.";});Action(a,"이름 변경",()=>{var p=Dispatcher.Invoke(new Func<ProfileEntry>(()=>profileList.SelectedItem as ProfileEntry));if(p==null||p.Builtin)throw new ArgumentException("사용자가 만든 프로필을 선택하세요.");string name=Dispatcher.Invoke(new Func<string>(()=>Prompt("프로필 이름 변경",p.Name)));if(name==null)return "이름 변경을 취소했습니다.";vm.Service.RenameProfile(p.Id,name);Dispatcher.Invoke((Action)(()=>Show("profiles")));return "프로필 이름을 저장했습니다.";});Action(a,"사용자 프로필 삭제",()=>{var p=Dispatcher.Invoke(new Func<ProfileEntry>(()=>profileList.SelectedItem as ProfileEntry));if(p==null||p.Builtin)throw new ArgumentException("기본 프로필은 삭제하지 않습니다.");if(Dispatcher.Invoke(new Func<bool>(()=>Decide("프로필 삭제",p.Name+"을 삭제할까요? 이전 파일은 프로젝트 백업에 보존합니다.","삭제","취소")==0))){vm.Service.DeleteProfile(p.Id);Dispatcher.Invoke((Action)(()=>Show("profiles")));return "프로필을 백업으로 이동했습니다.";}return "삭제를 취소했습니다.";});}
  void BuildGallery(){Text("설치된 Lively 라이브러리만 표시합니다. 썸네일 보기는 배경을 변경하거나 영상을 재생하지 않습니다.",true);assignmentText=new TextBlock{Text=vm.Service.WallpaperAssignments(),Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,14)};content.Children.Add(assignmentText);WatchWallpaper();var a=Actions();Action(a,"재생",Desktop("wallpaper-play"));Action(a,"일시정지",Desktop("wallpaper-pause"));Action(a,"정적 배경 전환",()=>{if(!Dispatcher.Invoke(new Func<bool>(()=>Decide("정적 배경 전환","라이브 배경을 닫고 현재 구성의 정적 대체 이미지를 적용할까요?","정적 배경 적용","취소")==0)))return "배경 전환을 취소했습니다.";vm.Service.Action("wallpaper-static");return "정적 대체 배경 요청을 완료했습니다.";});Action(a,"Lively 설정",Desktop("wallpaper-settings"));targetDisplay=new ComboBox{ItemsSource=vm.Service.Displays(),SelectedIndex=0,Margin=new Thickness(0,0,0,12)};AutomationProperties.SetName(targetDisplay,"배경 대상 디스플레이");content.Children.Add(targetDisplay);wallpaperList=new ListBox{Height=290,Background=Secondary,Foreground=TextColor,BorderBrush=Line};AutomationProperties.SetName(wallpaperList,"설치된 배경화면 갤러리");System.Windows.Controls.VirtualizingStackPanel.SetIsVirtualizing(wallpaperList,true);ScrollViewer.SetCanContentScroll(wallpaperList,true);content.Children.Add(wallpaperList);RefreshGallery();a=Actions();Action(a,"썸네일 크게 보기",()=>{var p=SelectedWallpaper();Dispatcher.Invoke((Action)(()=>PreviewThumbnail(p)));return "썸네일 미리보기를 닫았습니다.";});Action(a,"선택 화면에 적용",()=>ApplyGallery(false));Action(a,"모든 화면에 적용",()=>ApplyGallery(true));Action(a,"즐겨찾기 전환",()=>{var p=SelectedWallpaper();vm.Service.FavoriteWallpaper(p.Path);Dispatcher.Invoke((Action)RefreshGallery);return "배경 즐겨찾기를 저장했습니다.";});Action(a,"목록 다시 읽기",()=>{Dispatcher.Invoke((Action)RefreshGallery);return "설치된 배경 메타데이터를 다시 읽었습니다.";});}
  void WatchWallpaper(){if(wallpaperWatcher!=null)return;string path=vm.Service.WallpaperLayoutFile;if(!Directory.Exists(Path.GetDirectoryName(path)))return;wallpaperDebounce.Interval=TimeSpan.FromMilliseconds(350);wallpaperDebounce.Tick+=delegate{wallpaperDebounce.Stop();if(page=="wallpaper"&&!busy){try{assignmentText.Text=vm.Service.WallpaperAssignments();string id=targetDisplay.SelectedItem is DisplayEntry?((DisplayEntry)targetDisplay.SelectedItem).Id:"";var displays=vm.Service.Displays();targetDisplay.ItemsSource=displays;targetDisplay.SelectedItem=displays.FirstOrDefault(x=>x.Id==id)??displays.FirstOrDefault();RefreshGallery();}catch(Exception e){vm.Status="갤러리 갱신 확인 필요: "+e.Message;}}};wallpaperWatcher=new System.IO.FileSystemWatcher(Path.GetDirectoryName(path),Path.GetFileName(path));System.IO.FileSystemEventHandler changed=delegate{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke((Action)delegate{wallpaperDebounce.Stop();wallpaperDebounce.Start();});};wallpaperWatcher.Changed+=changed;wallpaperWatcher.Created+=changed;wallpaperWatcher.Renamed+=delegate{changed(null,null);};wallpaperWatcher.EnableRaisingEvents=true;Closed+=delegate{wallpaperDebounce.Stop();wallpaperWatcher.Dispose();};}
  WallpaperEntry SelectedWallpaper(){return Dispatcher.Invoke(new Func<WallpaperEntry>(()=>{var item=wallpaperList.SelectedItem as ListBoxItem;var p=item==null?null:item.Tag as WallpaperEntry;if(p==null)throw new ArgumentException("배경을 선택하세요.");return p;}));}
  ImageSource Thumbnail(WallpaperEntry p){try{if(String.IsNullOrEmpty(p.Thumbnail)||!File.Exists(p.Thumbnail)||new FileInfo(p.Thumbnail).Length>20*1024*1024)return null;var image=new System.Windows.Media.Imaging.BitmapImage();image.BeginInit();image.CacheOption=System.Windows.Media.Imaging.BitmapCacheOption.OnLoad;image.DecodePixelWidth=240;image.UriSource=new Uri(p.Thumbnail);image.EndInit();image.Freeze();return image;}catch{return null;}}
  void RefreshGallery(){wallpaperList.Items.Clear();foreach(var p in vm.Service.Wallpapers()){var panel=new StackPanel{Orientation=Orientation.Horizontal};var image=new Image{Width=100,Height=60,Margin=new Thickness(0,0,14,0),Stretch=Stretch.UniformToFill};image.Loaded+=delegate{if(image.Source==null)image.Source=Thumbnail(p);};panel.Children.Add(image);panel.Children.Add(new TextBlock{Text=p.ToString()+"\n"+(p.Customizable?"Lively 개별 설정 있음":"개별 설정 없음"),TextWrapping=TextWrapping.Wrap,MaxWidth=430,VerticalAlignment=VerticalAlignment.Center});var item=new ListBoxItem{Content=panel,Tag=p,Padding=new Thickness(6)};AutomationProperties.SetName(item,p.ToString());wallpaperList.Items.Add(item);}if(wallpaperList.Items.Count>0){wallpaperList.SelectedItem=wallpaperList.Items.Cast<ListBoxItem>().FirstOrDefault(i=>!String.IsNullOrEmpty(((WallpaperEntry)i.Tag).Assigned))??wallpaperList.Items[0];wallpaperList.ScrollIntoView(wallpaperList.SelectedItem);}else vm.Status="검색 가능한 Lively 패키지가 없습니다. Lively에서 라이브러리 위치를 확인하세요.";}
  string ApplyGallery(bool all){var p=SelectedWallpaper();var screen=Dispatcher.Invoke(new Func<DisplayEntry>(()=>targetDisplay.SelectedItem as DisplayEntry));if(screen==null)throw new ArgumentException("화면을 선택하세요.");if(!Dispatcher.Invoke(new Func<bool>(()=>Decide("배경 적용",p.Title+"\n대상: "+(all?"현재 연결된 모든 화면":screen.Label)+"\n현재 배경 배치를 백업한 뒤 변경합니다.","이 배경 적용","취소")==0)))return "배경 적용을 취소했습니다.";var result=vm.Service.ApplyWallpaper(p.Path,screen.Id,all);Dispatcher.Invoke((Action)RefreshGallery);return result;}
  void PreviewThumbnail(WallpaperEntry p){var image=new Image{Source=Thumbnail(p),Stretch=Stretch.Uniform};if(image.Source==null){vm.Status="사용할 수 있는 썸네일이 없습니다.";return;}var w=new Window{Title=p.Title+" · 썸네일",Owner=this,Width=720,Height=480,Background=Surface,Content=image,WindowStartupLocation=WindowStartupLocation.CenterOwner};w.ShowDialog();}
  void BuildSensors(){Text("센서 연결 안내",false);sensorDetails=new TextBlock{TextWrapping=TextWrapping.Wrap,Foreground=Muted,Margin=new Thickness(0,0,0,16)};content.Children.Add(sensorDetails);foreach(var f in vm.Fields)AddField(f);Text("1 공급자 확인 → 2 내보낸 값 → 3 장치·단위 선택 → 4 검증 후 저장",true);metricPicker=new ComboBox{ItemsSource=new[]{new ChoiceOption("CpuTemperatureC","CPU 온도 · °C"),new ChoiceOption("GpuTemperatureC","GPU 온도 · °C"),new ChoiceOption("SsdTemperatureC","물리 SSD 온도 · °C"),new ChoiceOption("CpuPackagePowerW","CPU 패키지 전력 · W")},DisplayMemberPath="Value",SelectedValuePath="Key",SelectedIndex=0,Margin=new Thickness(0,0,0,10)};AutomationProperties.SetName(metricPicker,"연결할 측정 항목");content.Children.Add(metricPicker);sensorPicker=new ComboBox{Margin=new Thickness(0,0,0,10)};AutomationProperties.SetName(sensorPicker,"실제 HWiNFO 센서 목록");content.Children.Add(sensorPicker);metricPicker.SelectionChanged+=delegate{LoadWizardSensors();};var a=Actions();Action(a,"실제 센서 다시 읽기",()=>{Dispatcher.Invoke((Action)LoadWizardSensors);return "기존 HWiNFO 제공자에서 실제 값을 다시 읽었습니다.";});connectSensor=Action(a,"선택한 센서 검증 · 연결",()=>{var result=SaveSensor();Dispatcher.Invoke((Action)LoadWizardSensors);return result;});Action(a,"HWiNFO 폴더",()=>{vm.Service.Open(Path.Combine(root,"apps","HWiNFO"));return "HWiNFO 폴더를 열었습니다. 관리자 실행은 별도 승인이 필요합니다.";});LoadWizardSensors();}
  void LoadWizardSensors(){if(sensorPicker==null||metricPicker==null)return;liveSensors=vm.Service.SensorSnapshot();var readings=liveSensors.ContainsKey("TemperatureReadings")?liveSensors["TemperatureReadings"] as IEnumerable:null;string metric=Convert.ToString(metricPicker.SelectedValue),unit=metric=="CpuPackagePowerW"?"W":"°C";var items=new List<ComboBoxItem>();if(readings!=null)foreach(var x in readings){var d=x as Dictionary<string,object>;if(d==null||DesktopService.S(d,"Unit")!=unit)continue;string device=DesktopService.S(d,"Sensor");if(metric.StartsWith("Cpu")&&device.IndexOf("CPU [",StringComparison.OrdinalIgnoreCase)<0)continue;if(metric.StartsWith("Gpu")&&device.IndexOf("GPU [",StringComparison.OrdinalIgnoreCase)<0)continue;items.Add(new ComboBoxItem{Content=SensorDisplay(device)+" / "+DesktopService.S(d,"Label")+" · "+DesktopService.S(d,"Formatted")+" ["+DesktopService.S(d,"Quality")+"]",Tag=d});}sensorPicker.ItemsSource=items;if(items.Count>0)sensorPicker.SelectedIndex=0;if(connectSensor!=null)connectSensor.IsEnabled=items.Any(i=>DesktopService.S((Dictionary<string,object>)i.Tag,"Quality")=="valid");RefreshSensorDetails();}
  static string SensorDisplay(string value){return System.Text.RegularExpressions.Regex.Replace(value,@"\([A-Z0-9]{10,}\)","[장치 ID 가림]");}
  static string SensorTime(string value){DateTimeOffset stamp;return DateTimeOffset.TryParse(value,out stamp)?stamp.ToLocalTime().ToString("HH:mm:ss"):"확인 불가";}
  void RefreshSensorDetails(){if(sensorDetails==null)return;try{var data=vm.Service.SensorSnapshot();var running=Process.GetProcessesByName("HWiNFO64").Length>0;bool installed=File.Exists(Path.Combine(root,"apps","HWiNFO","HWiNFO64.exe"))||File.Exists(DesktopService.S(vm.Service.Read("sensors"),"providerPath"));string category=!installed?"공급자 경로 없음 · HWiNFO 설치 위치를 연결하세요.":!running?"HWiNFO 중지 · 센서 창을 열어 두세요. 관리자 실행은 직접 승인해야 합니다.":DesktopService.S(data,"TemperatureQuality")=="unavailable"?"내보내기 없음 · HWiNFO 센서 설정에서 가젯 보고를 켜세요.":DesktopService.S(data,"TemperatureQuality")=="stale"?"오래된 값 · 센서 창과 가젯 갱신을 확인하세요.":DesktopService.S(data,"TemperatureQuality")=="mapping-required"?"장치 연결 필요 · 알맞은 단위와 장치를 선택하세요.":"실제 센서 연결됨";var lines=new List<string>{category};foreach(var pair in new[]{new[]{"CpuTemperatureC","CPU 온도","°C"},new[]{"GpuTemperatureC","GPU 온도","°C"},new[]{"SsdTemperatureC","물리 저장장치 온도","°C"},new[]{"CpuPackagePowerW","CPU 패키지 전력","W"}})lines.Add(pair[1]+": "+(data.ContainsKey(pair[0])&&data[pair[0]]!=null?Convert.ToString(data[pair[0]],CultureInfo.InvariantCulture)+" "+pair[2]:"사용 불가"));var list=data["TemperatureReadings"] as IEnumerable;if(list!=null)foreach(var value in list){var d=value as Dictionary<string,object>;if(d!=null&&d.ContainsKey("MappedMetric"))lines.Add(SensorDisplay(DesktopService.S(d,"Sensor"))+" / "+DesktopService.S(d,"Label")+" · 갱신 "+SensorTime(DesktopService.S(d,"ProviderUpdatedUtc"))+" · "+(DesktopService.S(d,"Quality")=="valid"?"정상":DesktopService.S(d,"Quality")));}sensorDetails.Text=String.Join("\n",lines);}catch(Exception e){sensorDetails.Text="센서 확인 불가: "+e.Message;}}
  void BuildDiagnostics(){Text("구성 요소별 상태와 지원되는 복구만 제공합니다. Explorer는 재시작하지 않습니다.",true);foreach(var row in vm.Service.Health())StatusRow(row,false);Text("File Explorer Styler는 기존 XAML diagnostics 충돌 때문에 비활성 상태를 유지합니다.",true);var a=Actions();Action(a,"진단 다시 실행",()=>{Dispatcher.Invoke((Action)(()=>Show("diagnostics")));return "현재 시각으로 진단을 갱신했습니다.";});Action(a,"개인정보 가린 보고서 내보내기",()=>{string file=null;Dispatcher.Invoke((Action)delegate{var dialog=new Microsoft.Win32.SaveFileDialog{Title="진단 보고서 저장",Filter="텍스트 파일|*.txt",FileName="GUnT-diagnostics-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".txt"};if(dialog.ShowDialog(this)==true)file=dialog.FileName;});if(file==null)return "내보내기를 취소했습니다.";File.WriteAllText(file,vm.Service.DiagnosticReport(),System.Text.Encoding.UTF8);return "개인 경로·IP·인증 패턴을 가린 진단 보고서를 저장했습니다.";});Action(a,"위젯 새로고침",Desktop("monitor-reload"));Action(a,"배치 복원",Desktop("layout-restore"));a=Actions();Action(a,"설정 체크포인트 저장",()=>vm.Service.Script("checkpoint","-Name user-v25"));Action(a,"구성 요소 복구 안내",()=>{vm.Service.Open(Path.Combine(root,"docs","v25-recovery.md"));return "구성 요소별 복구 안내를 열었습니다.";});var snapshots=vm.Service.ConfigurationSnapshots();var snapshotPicker=new ComboBox{ItemsSource=snapshots.Select(path=>new ChoiceOption(path,Path.GetFileName(path)+" · "+File.GetLastWriteTime(path).ToString("MM-dd HH:mm:ss"))).ToArray(),DisplayMemberPath="Value",SelectedValuePath="Key",Margin=new Thickness(0,8,0,8)};AutomationProperties.SetName(snapshotPicker,"설정 스냅샷 목록");if(snapshotPicker.Items.Count>0)snapshotPicker.SelectedIndex=0;content.Children.Add(snapshotPicker);var recover=Actions();Action(recover,"선택 설정 스냅샷 복원",()=>{string path=Dispatcher.Invoke(new Func<string>(()=>Convert.ToString(snapshotPicker.SelectedValue)));if(String.IsNullOrEmpty(path))throw new ArgumentException("복원할 설정 백업이 없습니다.");if(!Dispatcher.Invoke(new Func<bool>(()=>Decide("설정 하나 복원",Path.GetFileName(path)+" · "+File.GetLastWriteTime(path).ToString("g")+"\n이 설정만 현재 값과 비교해 복원합니다. 적용 실패 시 기존 트랜잭션으로 되돌립니다.\n\n"+vm.Service.SnapshotPreview(path),"이 설정 복원","취소")==0)))return "스냅샷 복원을 취소했습니다.";return vm.Service.RestoreConfigurationSnapshot(path);});Action(a,"Windhawk 구성 복구",()=>{if(!Dispatcher.Invoke(new Func<bool>(()=>Decide("Windhawk만 복구","확장 전 Windhawk 설정으로 복구합니다. 다른 구성 요소와 Explorer는 변경하지 않습니다.","Windhawk 구성 복구","취소")==0)))return "복구를 취소했습니다.";return vm.Service.Script("rollback-windhawk-enhancement","");});}
  void OpenCommandPalette(){var commands=new[]{new[]{"프로젝트 열기","projects"},new[]{"시스템 모니터 표시","action:monitor-show"},new[]{"배경화면 일시정지","action:wallpaper-pause"},new[]{"레이아웃 복원","action:layout-restore"},new[]{"개발 모드 미리보기","profile:Developer"},new[]{"시스템 모니터 설정","monitor"},new[]{"센서 상태 확인","sensors"},new[]{"프로필 미리보기","profiles"},new[]{"배경화면 갤러리","wallpaper"},new[]{"Dock 설정","dock"},new[]{"진단 및 복구","diagnostics"}};var w=new Window{Title="GUnT_0x9 명령 찾기",Owner=this,Width=550,Height=400,Background=Surface,Foreground=TextColor,FontFamily=FontFamily,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new DockPanel{Margin=new Thickness(16)};w.Content=panel;var query=new TextBox{Margin=new Thickness(0,0,0,12),Padding=new Thickness(8)};AutomationProperties.SetName(query,"GUNT 명령 검색");DockPanel.SetDock(query,Dock.Top);panel.Children.Add(query);var list=new ListBox{Background=Secondary,Foreground=TextColor};panel.Children.Add(list);Action filter=()=>{list.ItemsSource=commands.Where(c=>c[0].IndexOf(query.Text,StringComparison.OrdinalIgnoreCase)>=0).Select(c=>new ListBoxItem{Content=c[0],Tag=c[1]}).ToArray();if(list.Items.Count>0)list.SelectedIndex=0;};query.TextChanged+=delegate{filter();};Action execute=()=>{var item=list.SelectedItem as ListBoxItem;if(item==null)return;string target=Convert.ToString(item.Tag);w.Close();if(target.StartsWith("action:"))Run(Desktop(target.Substring(7)));else if(target.StartsWith("profile:")){SelectPage("profiles");profileList.SelectedItem=profileList.Items.Cast<ProfileEntry>().FirstOrDefault(p=>p.Id==target.Substring(8));}else SelectPage(target);};w.PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Escape){w.Close();e.Handled=true;}else if(e.Key==Key.Enter){execute();e.Handled=true;}else if(e.Key==Key.Down||e.Key==Key.Up){if(list.Items.Count>0){list.SelectedIndex=Math.Max(0,Math.Min(list.Items.Count-1,list.SelectedIndex+(e.Key==Key.Down?1:-1)));list.ScrollIntoView(list.SelectedItem);}e.Handled=true;}};list.MouseDoubleClick+=delegate{execute();};filter();w.Loaded+=delegate{query.Focus();};w.ShowDialog();}
